const input = $input.first().json;
const sales = (input.sales_analytics || []);
const metrics = input.metrics || {};

// ── Basic counts ──
const total_sales = sales.length;
if (total_sales === 0) {
  return { json: { error: "No sales data found", brand: metrics.brand || "Unknown" } };
}

const total_revisions = sales.filter(s => (s["Had Revision (0/1)"] ?? 0) === 1).length;
const revision_rate = parseFloat((total_revisions / total_sales).toFixed(3));

// ── Averages ──
const avg_days_to_close = parseFloat((sales.reduce((sum, s) => sum + (s["Days to Close"] || 0), 0) / total_sales).toFixed(1));
const avg_hold_time = parseFloat((sales.reduce((sum, s) => sum + (s["Hold Time (Days)"] || 0), 0) / total_sales).toFixed(1));
const avg_net_fee = parseFloat((sales.reduce((sum, s) => sum + (s["Net Fee ($)"] || 0), 0) / total_sales).toFixed(2));
const avg_transaction_fee = parseFloat((sales.reduce((sum, s) => sum + (s["Transaction Fee ($)"] || 0), 0) / total_sales).toFixed(2));

// ── Status breakdown ──
const status_breakdown = {};
sales.forEach(s => {
  const status = s.Status || "Unknown";
  status_breakdown[status] = (status_breakdown[status] || 0) + 1;
});

// ── Top revision cause ──
const cause_counts = {};
sales.forEach(s => {
  const cause = s["Top Revision Cause"];
  if (cause && cause !== "None") {
    cause_counts[cause] = (cause_counts[cause] || 0) + 1;
  }
});
const top_revision_cause = Object.entries(cause_counts)
  .sort((a, b) => b[1] - a[1])
  .map(([cause, count]) => ({ cause, count }));

// ── FD breakdown ──
const fd_map = {};
sales.forEach(s => {
  const fd = s["FD (Financial Director)"] || "Unknown";
  if (!fd_map[fd]) fd_map[fd] = { sales: 0, revisions: 0, total_days_to_close: 0 };
  fd_map[fd].sales += 1;
  fd_map[fd].revisions += (s["Had Revision (0/1)"] ?? 0);
  fd_map[fd].total_days_to_close += (s["Days to Close"] || 0);
});

const fd_breakdown = {};
Object.entries(fd_map).forEach(([fd, data]) => {
  fd_breakdown[fd] = {
    sales: data.sales,
    revisions: data.revisions,
    revision_rate: parseFloat((data.revisions / data.sales).toFixed(3)),
    avg_days_to_close: parseFloat((data.total_days_to_close / data.sales).toFixed(1))
  };
});

// ── Fee range ──
const net_fees = sales.map(s => s["Net Fee ($)"] || 0);
const fee_range = {
  min: parseFloat(Math.min(...net_fees).toFixed(2)),
  max: parseFloat(Math.max(...net_fees).toFixed(2))
};

// ── Final payload for LLM ──
return {
  json: {
    brand: metrics.brand || "Unknown",
    calculated: {
      total_sales,
      total_revisions,
      revision_rate,
      avg_days_to_close,
      avg_hold_time_days: avg_hold_time,
      avg_net_fee,
      avg_transaction_fee,
      fee_range,
      top_revision_cause: top_revision_cause.length > 0 ? top_revision_cause : null,
      status_breakdown,
      fd_breakdown
    },
    brand_baseline: metrics.filtered_brand_metrics || null,
    global_baseline: metrics.global_metrics || null
  }
};

